import{_ as t,o as d,c as o,a2 as a}from"./chunks/framework.D9DTPhg1.js";const u=JSON.parse('{"title":"Events","description":"","frontmatter":{},"headers":[],"relativePath":"reference/events.md","filePath":"packages/orm/docs/reference/events.md"}'),r={name:"reference/events.md"};function n(h,e,i,c,s,l){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="events" tabindex="-1">Events <a class="header-anchor" href="#events" aria-label="Permalink to &quot;Events&quot;">​</a></h1><p>Prism publishes typed PSR-14 events through the event dispatcher of each entity manager. In Symfony, listen to them with <a href="/prism/reference/attributes#asprismlistener"><code>#[AsPrismListener]</code></a>; without Symfony, pass any PSR-14 dispatcher to the <code>EntityManager</code>:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$em </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> EntityManager</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">($connection, $metadata, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">events</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: $dispatcher);</span></span></code></pre></div><p>For the events of one entity class, <a href="/prism/guide/mapping#lifecycle-callbacks">lifecycle callbacks</a> on the entity or <a href="/prism/reference/attributes#entitylisteners">entity listeners</a> are simpler: they receive the entity directly.</p><p>All events are in <code>Prism\\Orm\\Event</code>, except <code>NPlusOneDetected</code>, in <code>Prism\\Orm\\Debug</code>. Their properties are <code>readonly</code>.</p><p>The <code>unitOfWork</code> property of an event is a <code>Prism\\Orm\\UnitOfWork\\FlushContext</code>: what a listener may see and do during a flush. It lists the entities to insert, update and delete (<code>getScheduledInsertions()</code>, <code>getScheduledUpdates()</code>, <code>getScheduledDeletions()</code>), tells whether anything would be written (<code>hasPendingChanges()</code>), gives the state of an entity (<code>contains()</code>, <code>getEntityState()</code>), and accepts <code>persist()</code> and <code>remove()</code> from <code>PreFlushEvent</code> or <code>OnFlushEvent</code>, which this same flush then writes. The rest of the unit of work is internal to Prism.</p><h2 id="flush" tabindex="-1">Flush <a class="header-anchor" href="#flush" aria-label="Permalink to &quot;Flush&quot;">​</a></h2><p>A flush publishes <code>PreFlushEvent</code> and <code>OnFlushEvent</code> before its transaction, <code>PrePersistEvent</code> and <code>PreUpdateEvent</code> for each entity inside it, then after the commit <code>PostPersistEvent</code>, <code>PostUpdateEvent</code>, <code>PostRemoveEvent</code> and <code>AuditRecordedEvent</code>, and <code>PostFlushEvent</code> last. If the flush fails, nothing is published after the rollback. Calling <code>flush()</code> from a listener throws <code>ReentrantFlushException</code>.</p><h3 id="preflushevent" tabindex="-1"><code>PreFlushEvent</code> <a class="header-anchor" href="#preflushevent" aria-label="Permalink to &quot;`PreFlushEvent`&quot;">​</a></h3><p>At the start of <code>flush()</code>, before any change is computed: an entity persisted or modified here is written by this flush.</p><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th></th></tr></thead><tbody><tr><td><code>unitOfWork</code></td><td><code>FlushContext</code></td><td></td></tr></tbody></table><h3 id="onflushevent" tabindex="-1"><code>OnFlushEvent</code> <a class="header-anchor" href="#onflushevent" aria-label="Permalink to &quot;`OnFlushEvent`&quot;">​</a></h3><p>The changes are computed, before the transaction starts. <code>FlushContext::getScheduled*()</code> lists them; a change made here is included.</p><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th></th></tr></thead><tbody><tr><td><code>unitOfWork</code></td><td><code>FlushContext</code></td><td></td></tr></tbody></table><h3 id="prepersistevent" tabindex="-1"><code>PrePersistEvent</code> <a class="header-anchor" href="#prepersistevent" aria-label="Permalink to &quot;`PrePersistEvent`&quot;">​</a></h3><p>Before the <code>INSERT</code> of an entity, in the transaction of the flush; a change to the entity is inserted.</p><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th></th></tr></thead><tbody><tr><td><code>entity</code></td><td><code>object</code></td><td>The entity</td></tr><tr><td><code>unitOfWork</code></td><td><code>FlushContext</code></td><td></td></tr></tbody></table><h3 id="preupdateevent" tabindex="-1"><code>PreUpdateEvent</code> <a class="header-anchor" href="#preupdateevent" aria-label="Permalink to &quot;`PreUpdateEvent`&quot;">​</a></h3><p>Before the <code>UPDATE</code> of an entity; a change to the entity is included, and only that entity&#39;s changeset is computed again.</p><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th></th></tr></thead><tbody><tr><td><code>entity</code></td><td><code>object</code></td><td>The entity</td></tr><tr><td><code>changeSet</code></td><td><code>array&lt;string, array{mixed, mixed}&gt;</code></td><td>Field → [old value, new value]</td></tr><tr><td><code>unitOfWork</code></td><td><code>FlushContext</code></td><td></td></tr></tbody></table><h3 id="postpersistevent" tabindex="-1"><code>PostPersistEvent</code> <a class="header-anchor" href="#postpersistevent" aria-label="Permalink to &quot;`PostPersistEvent`&quot;">​</a></h3><p>After the commit of the flush that inserted the entity, never inside its transaction.</p><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th></th></tr></thead><tbody><tr><td><code>entity</code></td><td><code>object</code></td><td>The entity, with its generated identifier</td></tr><tr><td><code>unitOfWork</code></td><td><code>FlushContext</code></td><td></td></tr></tbody></table><h3 id="postupdateevent" tabindex="-1"><code>PostUpdateEvent</code> <a class="header-anchor" href="#postupdateevent" aria-label="Permalink to &quot;`PostUpdateEvent`&quot;">​</a></h3><p>After the commit of the flush that updated the entity.</p><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th></th></tr></thead><tbody><tr><td><code>entity</code></td><td><code>object</code></td><td>The entity</td></tr><tr><td><code>unitOfWork</code></td><td><code>FlushContext</code></td><td></td></tr></tbody></table><h3 id="postremoveevent" tabindex="-1"><code>PostRemoveEvent</code> <a class="header-anchor" href="#postremoveevent" aria-label="Permalink to &quot;`PostRemoveEvent`&quot;">​</a></h3><p>After the commit of the flush that deleted the entity.</p><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th></th></tr></thead><tbody><tr><td><code>entity</code></td><td><code>object</code></td><td>The entity</td></tr><tr><td><code>unitOfWork</code></td><td><code>FlushContext</code></td><td></td></tr></tbody></table><h3 id="auditrecordedevent" tabindex="-1"><code>AuditRecordedEvent</code> <a class="header-anchor" href="#auditrecordedevent" aria-label="Permalink to &quot;`AuditRecordedEvent`&quot;">​</a></h3><p>The audit rows written by a flush, published after its commit. The Audit panel of the Symfony profiler listens to it; listen to it to copy the log elsewhere.</p><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th></th></tr></thead><tbody><tr><td><code>entries</code></td><td><code>list&lt;AuditEntry&gt;</code></td><td>One entry per audited entity changed</td></tr></tbody></table><h3 id="postflushevent" tabindex="-1"><code>PostFlushEvent</code> <a class="header-anchor" href="#postflushevent" aria-label="Permalink to &quot;`PostFlushEvent`&quot;">​</a></h3><p>After the commit and the other <code>Post*</code> events; never after a failure.</p><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th></th></tr></thead><tbody><tr><td><code>unitOfWork</code></td><td><code>FlushContext</code></td><td></td></tr></tbody></table><h3 id="inversesidechangedevent" tabindex="-1"><code>InverseSideChangedEvent</code> <a class="header-anchor" href="#inversesidechangedevent" aria-label="Permalink to &quot;`InverseSideChangedEvent`&quot;">​</a></h3><p>At flush, a collection on the inverse side of a relation changed without its owning side: nothing is written for that change. An added element does not point to the owner, or a removed one still does. The Symfony bundle logs it as a warning in development.</p><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th></th></tr></thead><tbody><tr><td><code>owner</code></td><td><code>object</code></td><td>The entity whose collection changed</td></tr><tr><td><code>field</code></td><td><code>string</code></td><td>The collection property</td></tr><tr><td><code>element</code></td><td><code>object</code></td><td>The element added or removed</td></tr><tr><td><code>added</code></td><td><code>bool</code></td><td><code>true</code> if added, <code>false</code> if removed</td></tr><tr><td><code>unitOfWork</code></td><td><code>FlushContext</code></td><td></td></tr></tbody></table><h2 id="entities" tabindex="-1">Entities <a class="header-anchor" href="#entities" aria-label="Permalink to &quot;Entities&quot;">​</a></h2><h3 id="preremoveevent" tabindex="-1"><code>PreRemoveEvent</code> <a class="header-anchor" href="#preremoveevent" aria-label="Permalink to &quot;`PreRemoveEvent`&quot;">​</a></h3><p>When <code>remove()</code> is called, before the entity is scheduled for deletion.</p><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th></th></tr></thead><tbody><tr><td><code>entity</code></td><td><code>object</code></td><td>The entity</td></tr><tr><td><code>unitOfWork</code></td><td><code>FlushContext</code></td><td></td></tr></tbody></table><h3 id="postloadevent" tabindex="-1"><code>PostLoadEvent</code> <a class="header-anchor" href="#postloadevent" aria-label="Permalink to &quot;`PostLoadEvent`&quot;">​</a></h3><p>After an entity is loaded from the database: <code>find()</code>, <code>findBy()</code>, <code>iterate()</code>, a reference that loads, <code>refresh()</code>. Never for an entity that the identity map returns.</p><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th></th></tr></thead><tbody><tr><td><code>entity</code></td><td><code>object</code></td><td>The entity</td></tr><tr><td><code>unitOfWork</code></td><td><code>FlushContext</code></td><td></td></tr></tbody></table><h3 id="onclearevent" tabindex="-1"><code>OnClearEvent</code> <a class="header-anchor" href="#onclearevent" aria-label="Permalink to &quot;`OnClearEvent`&quot;">​</a></h3><p>After <code>clear()</code>: every entity is detached.</p><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th></th></tr></thead><tbody><tr><td><code>unitOfWork</code></td><td><code>FlushContext</code></td><td></td></tr></tbody></table><h2 id="diagnostics" tabindex="-1">Diagnostics <a class="header-anchor" href="#diagnostics" aria-label="Permalink to &quot;Diagnostics&quot;">​</a></h2><h3 id="batchloadedevent" tabindex="-1"><code>BatchLoadedEvent</code> <a class="header-anchor" href="#batchloadedevent" aria-label="Permalink to &quot;`BatchLoadedEvent`&quot;">​</a></h3><p>A batch load: one query for a whole cohort. Published only when the batch holds at least two entities; the Symfony profiler shows them.</p><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th></th></tr></thead><tbody><tr><td><code>entityClass</code></td><td><code>class-string</code></td><td>Without <code>association</code>: the class of the entities loaded together. With it: the class of the owners</td></tr><tr><td><code>association</code></td><td><code>?string</code></td><td><code>null</code> for referenced entities loaded together; otherwise the relation loaded for the owners (a collection, or the inverse side of a <code>OneToOne</code>)</td></tr><tr><td><code>count</code></td><td><code>int</code></td><td>The number of entities, or of owners</td></tr><tr><td><code>unitOfWork</code></td><td><code>FlushContext</code></td><td></td></tr></tbody></table><h3 id="nplusonedetected" tabindex="-1"><code>NPlusOneDetected</code> <a class="header-anchor" href="#nplusonedetected" aria-label="Permalink to &quot;`NPlusOneDetected`&quot;">​</a></h3><p><code>Prism\\Orm\\Debug\\NPlusOneDetected</code>, published by the <a href="/prism/guide/n-plus-one#the-n-1-detector">N+1 detector</a> when the same read query ran more times than its threshold since its last <code>reset()</code>. Published once per query.</p><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th></th></tr></thead><tbody><tr><td><code>sql</code></td><td><code>string</code></td><td>The normalized SQL: values and <code>IN</code> lists replaced by <code>?</code></td></tr><tr><td><code>count</code></td><td><code>int</code></td><td>How many times it ran</td></tr><tr><td><code>origin</code></td><td><code>string</code></td><td><code>file:line</code> of the first frame outside <code>vendor/</code> and Prism: the line of your code that started the loop</td></tr></tbody></table>',55)])])}const b=t(r,[["render",n]]);export{u as __pageData,b as default};
